<script setup>
import {ref,onMounted} from 'vue'
const token=ref(localStorage.token||''),user=ref(JSON.parse(localStorage.user||'null')),books=ref([]),total=ref(0),page=ref(1),q=ref(''),message=ref(''),username=ref(''),password=ref(''),form=ref({title:'',author:'',category:'',summary:'',coverUrl:''}),aiText=ref(''),aiAnswer=ref(''),prefs=ref(''),selected=ref([])
const headers=()=>({'Content-Type':'application/json',...(token.value?{Authorization:`Bearer ${token.value}`}:{})})
async function req(url,opts={}){let r=await fetch(url,{...opts,headers:{...headers(),...opts.headers}});let d=await r.json();if(!r.ok)throw Error(d.error||'请求失败');return d}
async function login(path){try{const d=await req('/api/auth/'+path,{method:'POST',body:JSON.stringify({username:username.value,password:password.value})});token.value=d.token;user.value=d.user;localStorage.token=d.token;localStorage.user=JSON.stringify(d.user);load()}catch(e){message.value=e.message}}
async function load(){try{let d=await req(`/api/books?page=${page.value}&q=${encodeURIComponent(q.value)}`);books.value=d.items;total.value=d.total}catch(e){message.value=e.message}}
async function save(){try{await req('/api/books',{method:'POST',body:JSON.stringify(form.value)});message.value='已新增';load()}catch(e){message.value=e.message}}
async function editBook(b){form.value={...b};try{await req('/api/books/'+b.id,{method:'PUT',body:JSON.stringify(form.value)});message.value='已更新';load()}catch(e){message.value=e.message}}
async function deleteBook(id){try{await req('/api/books/'+id,{method:'DELETE'});message.value='已删除';load()}catch(e){message.value=e.message}}
async function deleteSelected(){if(!selected.value.length)return;try{await req('/api/books/batch-delete',{method:'POST',body:JSON.stringify({ids:selected.value})});selected.value=[];message.value='批量删除完成';load()}catch(e){message.value=e.message}}
async function ai(action,payload){try{aiAnswer.value=(await req('/api/ai/'+action,{method:'POST',body:JSON.stringify(payload)})).answer}catch(e){aiAnswer.value=e.message}}
function logout(){localStorage.clear();token.value='';user.value=null}
onMounted(load)
</script>
<template><main><header><h1>📚 AI 智能图书资讯</h1><span v-if="user">{{user.username}} · {{user.role}} <button @click="logout">退出</button></span></header><p class="notice">{{message}}</p>
<section v-if="!user" class="card"><h2>登录 / 注册</h2><input v-model="username" placeholder="用户名"><input v-model="password" type="password" placeholder="密码（至少4位）"><button @click="login('login')">登录</button><button class="light" @click="login('register')">注册</button></section>
<section class="card"><h2>图书检索</h2><input v-model="q" placeholder="按书名搜索" @keyup.enter="load"><button @click="page=1;load()">搜索</button><button v-if="user?.role==='ADMIN'" class="light" @click="deleteSelected">批量删除所选</button><div class="grid"><article v-for="b in books" :key="b.id"><label v-if="user?.role==='ADMIN'"><input type="checkbox" :value="b.id" v-model="selected">选择</label><img v-if="b.coverUrl" :src="b.coverUrl"><h3>{{b.title}}</h3><p>{{b.author}} · {{b.category}}</p><p>{{b.summary}}</p><template v-if="user?.role==='ADMIN'"><button @click="form={...b};message='编辑后点击保存修改'">载入编辑</button><button class="light" @click="deleteBook(b.id)">删除</button></template></article></div><button :disabled="page<=1" @click="page--;load()">上一页</button> {{page}} / {{Math.max(1,Math.ceil(total/10))}} <button :disabled="page*10>=total" @click="page++;load()">下一页</button></section>
<section v-if="user?.role==='ADMIN'" class="card"><h2>管理员：图书编辑 / 新增</h2><input v-model="form.title" placeholder="书名"><input v-model="form.author" placeholder="作者"><input v-model="form.category" placeholder="分类"><textarea v-model="form.summary" placeholder="简介"></textarea><input v-model="form.coverUrl" placeholder="封面 URL"><input type="file" accept="image/*" @change="async e=>{let f=e.target.files[0];if(f){let fd=new FormData();fd.append('file',f);let r=await fetch('/api/upload',{method:'POST',headers:{Authorization:`Bearer ${token}`},body:fd});form.coverUrl=(await r.json()).url}}"><button @click="form.id?editBook(form):save()">保存</button></section>
<section class="card"><h2>AI 阅读助手</h2><textarea v-model="aiText" placeholder="粘贴图书简介或内容"></textarea><button @click="ai('interpret',{text:aiText})">智能解读</button><input v-model="prefs" placeholder="描述你的阅读偏好"><button @click="ai('recommend',{preferences:prefs})">智能推荐</button><input v-model="aiText" placeholder="向 AI 提问"><button @click="ai('chat',{message:aiText})">发送提问</button><pre>{{aiAnswer}}</pre></section></main></template>
